// src/hooks/useClaim.js
import { useContext, useState } from 'react';
import ClaimContext from '../context/ClaimContext.jsx';

/**
 * Custom hook to access claim context
 * @returns {Object} Claim context value
 * @throws {Error} If used outside of ClaimProvider
 */
export const useClaim = () => {
  const context = useContext(ClaimContext);
  if (!context) {
    throw new Error('useClaim must be used within a ClaimProvider');
  }
  return context;
};

/**
 * Hook for claim search functionality
 * @returns {Object} Search methods and state
 */
export const useClaimSearch = () => {
  const { fetchClaim, isLoading, error, currentClaim, setCurrentClaim } = useClaim();
  
  const searchClaim = async (msisdn) => {
    if (!msisdn || msisdn.trim().length < 10) {
      throw new Error('Please enter a valid phone number');
    }
    return await fetchClaim(msisdn.trim());
  };

  const clearSearch = () => {
    setCurrentClaim(null);
  };

  return {
    searchClaim,
    clearSearch,
    isLoading,
    error,
    currentClaim
  };
};

/**
 * Hook for claim history management
 * @returns {Object} History methods and data
 */
export const useClaimHistory = () => {
  const { claims, updateClaim } = useClaim();
  
  const getClaimByRef = (ref) => {
    return claims.find(c => c.covert_note_number === ref);
  };
  
  const getClaimsByStatus = (status) => {
    return claims.filter(c => c.status === status);
  };

  const getClaimsByDateRange = (startDate, endDate) => {
    return claims.filter(c => {
      const claimDate = new Date(c.created_at);
      return claimDate >= new Date(startDate) && claimDate <= new Date(endDate);
    });
  };

  const getRecentClaims = (limit = 5) => {
    return [...claims]
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
      .slice(0, limit);
  };

  return {
    claims,
    getClaimByRef,
    getClaimsByStatus,
    getClaimsByDateRange,
    getRecentClaims,
    updateClaim
  };
};

/**
 * Hook for claim statistics
 * @returns {Object} Statistics and metrics
 */
export const useClaimStats = () => {
  const { claims } = useClaim();
  
  const getStats = () => {
    const total = claims.length;
    const pending = claims.filter(c => c.status === 'PENDING' || c.status === 'PINS000').length;
    const verified = claims.filter(c => c.status === 'VERIFIED').length;
    const rejected = claims.filter(c => c.status === 'REJECTED').length;
    const completed = claims.filter(c => c.status === 'COMPLETED').length;
    
    return {
      total,
      pending,
      verified,
      rejected,
      completed,
      completionRate: total > 0 ? ((completed + verified) / total * 100).toFixed(1) : 0
    };
  };

  return {
    getStats,
    totalClaims: claims.length
  };
};

/**
 * Hook for claim form management
 * @param {Object} initialData - Initial claim data
 * @returns {Object} Form state and handlers
 */
export const useClaimForm = (initialData = null) => {
  const { addClaim, updateClaim } = useClaim();
  const [formData, setFormData] = useState(initialData || {});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState({});

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: null }));
    }
  };

  const validate = (data) => {
    const newErrors = {};
    // Add validation rules as needed
    if (!data.covert_note_number) {
      newErrors.covert_note_number = 'Claim reference is required';
    }
    if (!data.msisdn) {
      newErrors.msisdn = 'Phone number is required';
    }
    return newErrors;
  };

  const submit = async (data) => {
    setIsSubmitting(true);
    setErrors({});
    
    try {
      const validationErrors = validate(data);
      if (Object.keys(validationErrors).length > 0) {
        setErrors(validationErrors);
        throw new Error('Validation failed');
      }
      
      if (data.id) {
        await updateClaim(data.id, data);
      } else {
        await addClaim(data);
      }
      
      return { success: true, data };
    } catch (error) {
      return { success: false, error: error.message };
    } finally {
      setIsSubmitting(false);
    }
  };

  const reset = () => {
    setFormData(initialData || {});
    setErrors({});
    setIsSubmitting(false);
  };

  return {
    formData,
    setFormData,
    handleChange,
    submit,
    reset,
    isSubmitting,
    errors
  };
};

// Default export
export default useClaim;
